"""Authentication: password hashing (bcrypt) and JWT issuing/validation.

Plaintext passwords are never stored — only their bcrypt hash. A login issues a
signed JWT; every protected route depends on :func:`get_current_user`, which
decodes and validates that token and returns the username it represents.

Course mapping: this module implements *Authentication* ("prove who you are")
and stateless *session* handling via JWT — Meeting 4A, slides 8–11.
"""

import os
from datetime import datetime, timedelta, timezone
from typing import Optional

import bcrypt
from dotenv import load_dotenv
from fastapi import Depends, HTTPException, status
from fastapi.security import OAuth2PasswordBearer
from jose import JWTError, jwt

load_dotenv()

# Configuration comes from .env — never hard-code secrets.
SECRET_KEY = os.getenv("SECRET_KEY")
ALGORITHM = os.getenv("ALGORITHM", "HS256")
ACCESS_TOKEN_EXPIRE_MINUTES = int(os.getenv("ACCESS_TOKEN_EXPIRE_MINUTES", "60"))

# [SECURITY HARDENING] H-3: fail fast on a missing/placeholder signing key.
# A known key lets anyone forge a valid JWT and impersonate any user, so we
# refuse to start rather than run with an insecure secret. The token is the
# stateless equivalent of the course's "Session ID" (Meeting 4A) — its
# integrity depends entirely on this key staying secret.
_PLACEHOLDER_KEYS = {"", "change-me-in-dotenv", "your_random_secret_key_here"}
if not SECRET_KEY or SECRET_KEY in _PLACEHOLDER_KEYS:
    raise RuntimeError(
        "SECRET_KEY is missing or still the placeholder value. Set a strong "
        "random key in .env (e.g. `python -c \"import secrets; "
        "print(secrets.token_hex(32))\"`) before starting the server."
    )

# FastAPI extracts the "Authorization: Bearer <token>" header for us. The
# tokenUrl is informational (used by the interactive docs).
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="auth/login")

# bcrypt has a hard 72-byte limit on its input. We use the ``bcrypt`` library
# directly (rather than passlib) because passlib 1.7.4 is incompatible with
# bcrypt 5.x, the only release with wheels for Python 3.14.
_BCRYPT_MAX_BYTES = 72


def _encode(password: str) -> bytes:
    """UTF-8 encode and truncate to bcrypt's 72-byte limit."""
    return password.encode("utf-8")[:_BCRYPT_MAX_BYTES]


# --------------------------------------------------------------------------- #
# Passwords
# --------------------------------------------------------------------------- #
def hash_password(password: str) -> str:
    """Return a bcrypt hash of ``password`` suitable for storage."""
    return bcrypt.hashpw(_encode(password), bcrypt.gensalt()).decode("utf-8")


def verify_password(plain_password: str, hashed_password: str) -> bool:
    """Return ``True`` if ``plain_password`` matches the stored bcrypt hash."""
    try:
        return bcrypt.checkpw(_encode(plain_password), hashed_password.encode("utf-8"))
    except ValueError:
        # Malformed stored hash — treat as a failed match rather than crashing.
        return False


# --------------------------------------------------------------------------- #
# JWT tokens
# --------------------------------------------------------------------------- #
def create_access_token(username: str, expires_delta: Optional[timedelta] = None) -> str:
    """Create a signed JWT whose subject (``sub``) is the username."""
    expire = datetime.now(timezone.utc) + (
        expires_delta or timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    )
    payload = {"sub": username, "exp": expire}
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)


def decode_token(token: str) -> Optional[str]:
    """[SECURITY HARDENING] H-1: decode+validate a JWT, return its username.

    Returns ``None`` when the token is missing, malformed, expired, or has no
    subject. Shared by the HTTP dependency below and by the WebSocket handler so
    both enforce identity the same way (the connection is stateless and must
    prove who it is — Meeting 4A).
    """
    if not token:
        return None
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username = payload.get("sub")
        return username if isinstance(username, str) and username else None
    except JWTError:
        # Covers invalid signatures and expired tokens alike.
        return None


def get_current_user(token: str = Depends(oauth2_scheme)) -> str:
    """FastAPI dependency: validate the Bearer token and return the username.

    Raises HTTP 401 if the token is missing, malformed, expired, or its subject
    is absent. Protected routes simply add
    ``username: str = Depends(get_current_user)`` to gain authentication.
    """
    username = decode_token(token)
    if username is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Could not validate credentials",
            headers={"WWW-Authenticate": "Bearer"},
        )
    return username
